export const GetTripBookingsResponse: MessageFns<GetTripBookingsResponse> = {
  encode(message: GetTripBookingsResponse, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    for (const v of message.bookings) {
      BookingItem.encode(v!, writer.uint32(10).fork()).join();
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): GetTripBookingsResponse {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseGetTripBookingsResponse();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.bookings.push(BookingItem.decode(reader, reader.uint32()));
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): GetTripBookingsResponse {
    return {
      bookings: globalThis.Array.isArray(object?.bookings)
        ? object.bookings.map((e: any) => BookingItem.fromJSON(e))
        : [],
    };
  },

  toJSON(message: GetTripBookingsResponse): unknown {
    const obj: any = {};
    if (message.bookings?.length) {
      obj.bookings = message.bookings.map((e) => BookingItem.toJSON(e));
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<GetTripBookingsResponse>, I>>(base?: I): GetTripBookingsResponse {
    return GetTripBookingsResponse.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<GetTripBookingsResponse>, I>>(object: I): GetTripBookingsResponse {
    const message = createBaseGetTripBookingsResponse();
    message.bookings = object.bookings?.map((e) => BookingItem.fromPartial(e)) || [];
    return message;
  },
};

